using System;using System.Data;using System.Data.SqlClient;using System.Drawing;using System.Text;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class ResumeBuilderPage:UserControl{ComboBox candidate;TextBox summary,skills;public ResumeBuilderPage(){Dock=DockStyle.Fill;BackColor=Theme.Background;var p=Ui.Card();p.Dock=DockStyle.Top;p.Height=300;candidate=new ComboBox{Width=420,DropDownStyle=ComboBoxStyle.DropDownList};var dt=Database.Query("SELECT Id,FullName FROM Candidates ORDER BY FullName");candidate.DataSource=dt;candidate.DisplayMember="FullName";candidate.ValueMember="Id";candidate.SelectedIndexChanged+=(s,e)=>LoadResume();summary=new TextBox{Multiline=true,Width=650,Height=100,Top=55,ScrollBars=ScrollBars.Vertical};skills=new TextBox{Width=650,Top=170};var save=Ui.Button(L.Fa?"ذخیره رزومه حرفه‌ای":"Save resume profile");save.Top=215;save.Click+=(s,e)=>Save();p.Controls.Add(candidate);p.Controls.Add(summary);p.Controls.Add(skills);p.Controls.Add(save);Controls.Add(p);LoadResume();}int Id=>candidate.SelectedValue is int?(int)candidate.SelectedValue:Convert.ToInt32(candidate.SelectedValue??0);void LoadResume(){if(Id==0)return;var d=Database.Query("SELECT Summary FROM Candidates WHERE Id=@i",new SqlParameter("@i",Id));summary.Text=d.Rows.Count>0?Convert.ToString(d.Rows[0]["Summary"]):"";var s=Database.Query("SELECT Skill FROM CandidateSkills WHERE CandidateId=@i ORDER BY Skill",new SqlParameter("@i",Id));var a=new string[s.Rows.Count];for(int i=0;i<s.Rows.Count;i++)a[i]=Convert.ToString(s.Rows[i][0]);skills.Text=string.Join(", ",a);}void Save(){Database.Exec("UPDATE Candidates SET Summary=@s WHERE Id=@i",new SqlParameter("@s",summary.Text),new SqlParameter("@i",Id));Database.Exec("DELETE CandidateSkills WHERE CandidateId=@i",new SqlParameter("@i",Id));foreach(var x in skills.Text.Split(',')){var v=x.Trim();if(v.Length>0)Database.Exec("INSERT CandidateSkills(CandidateId,Skill,Level,Years) VALUES(@i,@s,'Intermediate',0)",new SqlParameter("@i",Id),new SqlParameter("@s",v));}Database.Audit("ResumeUpdate","Candidate",Id.ToString());MessageBox.Show(L.Fa?"رزومه ذخیره شد.":"Resume profile saved.");}}
}